rows[117905]={title={{25,1406122227},"상급 타락한 정수"},description={"^corruption courses through the protector's veins, increasing all damage done by ([%+%-]?%d[%d,.%+%-to –]*)%% per application%. if greater corrupted essence ever reaches 5 stacks, the greater essence of fear is unleashed%.$","타락이 정맥을 타고 돌며 공격력을 효과 하나당 \0311\031%만큼 증가시킵니다. 상급 타락한 정수의 효과가 5번 중복되면 상급 공포의 정수가 분출됩니다.",{0},{1}},aura={"^damage increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. reaching 5 stacks of greater corrupted essence unleashes the greater essence of fear%.$","공격력 \0311\031%만큼 증가\010상급 타락한 정수가 5번 중복되면 상급 공포의 정수 분출",{0},{1}}}
