rows[117907]={title={{28,1328987026},"특화: 용의 선물"},description={"^you have a ([%+%-]?%d[%d,.%+%-to –]*)%% chance when you heal to summon a healing sphere nearby an injured ally for ([%+%-]?%d[%d,.]* %a+)%. allies who walk through the sphere will be healed for ([%+%-]?%d[%d,.%+%-to –]*)%. if the healing sphere expires before being used, an ally nearby within ([%+%-]?%d[%d,.%+%-to –]*) yards of the sphere will be healed for ([%+%-]?%d[%d,.%+%-to –]*)%% of the effect%.$","치유에 성공하면 \0311\031%의 확률로 부상당한 아군 근처에 \0312\031 동안 유지되는 치유의 구슬을 소환합니다. 아군이 구슬을 통과하면 생명력이 \0313\031만큼 회복됩니다.\010\010치유의 구슬이 사용되지 않고 사라지면, 구슬로부터 \0314\031미터 반경 내에 있는 아군 하나의 생명력이 구슬 효과의 \0315\031%만큼 회복됩니다.",{0,1,0,0,0},{1,2,3,4,5}}}
