rows[119449]={title={{19,188763828},"문양: 위장술"},description={"^your camouflage ability now provides stealth even while moving, but your movement speed while camouflage is active is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","위장술 사용 시 이동 중에도 은신 효과가 적용되지만, 위장술이 활성화되어 있는 동안 이동 속도가 \0311\031%만큼 감소합니다.",{0},{1}}}
rows[119450]={title={{10,2062176690},"위장술"},description={"^you blend into your surroundings, causing you and your pet to be untargetable by ranged attacks%. also reduces the range at which enemy creatures can detect you, provides stealth, and reduces movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%%%. you can lay traps while camouflaged, but any damage done by you or your pet will cancel the effect%. cannot be cast while in combat%. lasts for ([%+%-]?%d[%d,.]* %a+)%.$","주위 환경에 맞게 사냥꾼과 야수의 모습을 위장하여, 적이 원거리 공격 대상으로 지정할 수 없게 합니다. 또한 적에게 감지당하는 범위가 감소하고, 정지한 동안 은신 상태가 되며, 이동 속도가 \0311\031%만큼 감소합니다.\010\010위장 중 덫을 설치할 수 있지만, 사냥꾼이나 야수가 공격을 가하면 위장이 풀립니다. 전투 중에는 사용할 수 없습니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={{11,1999642894},"은신 중"}}
