rows[121449]={title={{11,1457734029},"고무"},description={"^breaking out of the resin leaves you invigorated, increasing casting and movement speeds by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","나뭇진에서 자유로워지면 기분이 고무되어 시전 및 이동 속도가 \0312\031 동안 \0311\031%만큼 증가합니다.",{0,1},{1,2}},aura={"^casting speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%. movement speed increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","시전 속도 \0311\031%만큼 증가\010이동 속도 \0312\031%만큼 증가",{0,0},{1,2}}}
