rows[122710]={title={{9,1991679523},"경계"},description={"^focus your protective gaze on a party or raid member, transferring ([%+%-]?%d[%d,.%+%-to –]*)%% of damage taken to you for ([%+%-]?%d[%d,.]* %a+)%. during the duration of vigilance, your taunt has no cooldown and attacks against the target cause you to become enraged for ([%+%-]?%d[%d,.]* %a+)%.$","파티원이나 공격대원에게 보호의 시선을 집중하여, \0312\031 동안 대상이 받는 피해의 \0311\031%를 대신 받습니다.\010\010경계가 지속되는 동안은 도발을 재사용 대기시간 없이 사용할 수 있고, 대상이 공격을 받으면 \0313\031 동안 격노합니다.",{0,1,1},{1,2,3}},aura={"^transfers ([%+%-]?%d[%d,.%+%-to –]*)%% of incoming damage to the warrior%.$","받는 피해의 \0311\031%가 전사에게 이전",{0},{1}}}
rows[122713]={title={{15,576651855},"힘과 활력"},description={"^imperial vizier zor'lok creates a violent burst of sound, inflicting ([%+%-]?%d[%d,.%+%-to –]*) physical damage to all players every ([%+%-]?%d[%d,.%+%-to –]*) seconds for ([%+%-]?%d[%d,.]* %a+)%.$","황실 장로 조르로크가 우렁찬 소리를 터뜨려 모든 플레이어에게 \0313\031 동안 \0312\031초마다 \0311\031의 물리 피해를 입힙니다.",{0,0,1},{1,2,3}},aura={"^([%+%-]?%d[%d,.%+%-to –]*) physical damage to all players every ([%+%-]?%d[%d,.%+%-to –]*) seconds for ([%+%-]?%d[%d,.]* %a+)%.$","\0313\031 동안 \0312\031초마다 \0311\031의 물리 피해",{0,0,1},{1,2,3}}}
