rows[122842]={title={{13,1757914730},"폭풍의 베기"},description={"^slashes the air creating a tornado that deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage and knocks away any targets near it%.$","공중을 베어 폭풍을 만들어 냅니다. 폭풍은 \0311\031의 자연 피해를 입히고 주위 대상을 밀쳐냅니다.",{0},{1}},aura={"^slashes the air creating a tornado that deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage and knocks away any targets near it%.$","공중을 베어 폭풍을 만듦\010폭풍으로 \0311\031의 자연 피해\010주위 대상을 밀쳐냄",{0},{1}}}
